function normalise(path) {
    return String(path || "").replace(/^\.?\//, "").split("?")[0];
}

// Returns a srcset for a path, or "" when no variants exist for it.
export function srcsetFor(path) {
    return SRCSET[normalise(path)] || "";
}

// Attribute string to splice into an <img>. Empty when there is nothing to add,
// so callers can always append the result.
export function responsiveAttrs(path, sizes) {
    const srcset = srcsetFor(path);
    if (!srcset) return "";
    return ` srcset="${srcset}" sizes="${sizes}"`;
}
